mapper.select:
select t.id, t.title, t.status, t.priority, t.start_time, t.due_time, t.finish_time, case when t.due_time is null then false when t.finish_time is null then t.due_time < now() else t.finish_time > t.due_time end as is_overdue, ( select max(tr.create_time) from task_record tr where tr.task_id = t.id and tr.action_type = 1 ) as latest_submit_time, owner_su.user_id as owner_user_id, owner_su.avatar as owner_avatar, owner_su.nick_name as owner_nick_name from task t left join task_user owner_tu on owner_tu.task_id = t.id and owner_tu.task_role = 2 left join sys_user owner_su on owner_su.user_id = owner_tu.user_id and owner_su.del_flag = 0
t.del_flag = 0
and t.title like concat('%', #{query.title}, '%')
and t.status = #{query.status}
and t.priority = #{query.priority}
and exists ( select 1 from task_user filter_tu where filter_tu.task_id = t.id and filter_tu.user_id = #{query.userId} )
and t.create_time >= #{query.startTime}
and t.due_time <= #{query.endTime}
order by t.create_time desc

select count(1)
from task_user tu
inner join task t on t.id = tu.task_id and t.del_flag = 0
where tu.task_id = #{taskId}
  and tu.user_id = #{userId}
